package com.witchersbestiary.test;
import com.witchersbestiary.fist.*;import com.witchersbestiary.economy.WalletTransactions;import net.fabricmc.api.ModInitializer;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.minecraft.server.MinecraftServer;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.math.BlockPos;import net.minecraft.item.ItemStack;import java.nio.file.*;import java.util.*;import com.google.gson.*;
public final class Stage21BNetworkServer implements ModInitializer{
 private Path dir;private int phase,ticks;private final String[] names={"WBOne","WBTwo"};private final FistNpc[] npcs=new FistNpc[3];private final FistFights.Active[] rounds=new FistFights.Active[2];private final Map<String,Object> results=new LinkedHashMap<>();private long nonce=31000;private int stopped;private double[] balances=new double[2];private float[] health=new float[2];
 private ServerPlayerEntity player(MinecraftServer s,int i){return s.getPlayerManager().getPlayer(names[i]);}
 private void write(String file,Object data)throws Exception{Files.writeString(dir.resolve(file),new Gson().toJson(data));}
 private void command(int i,String action,int npc)throws Exception{var j=new JsonObject();j.addProperty("nonce",++nonce);j.addProperty("action",action);j.addProperty("npc",npc);write(names[i]+".command.json",j);}
 private void fight(MinecraftServer s,int i,int tier)throws Exception{var p=player(s,i);var n=npcs[tier];n.setAiDisabled(true);p.closeHandledScreen();p.getInventory().selectedSlot=0;p.teleport(s.getOverworld(),n.getX()-2,n.getY(),n.getZ(),-90,0);rounds[i]=null;command(i,"fistFlow",n.getId());}
 public void onInitialize(){if(!Boolean.getBoolean("witchersbestiary.stage21bNetwork"))return;dir=Path.of(System.getProperty("witchersbestiary.stage20eOutput"));if(Files.exists(dir.resolve("fist-resume.json")))phase=10;ServerTickEvents.END_SERVER_TICK.register(s->{try{if(phase==99){if(++stopped>60)s.stop(false);return;}if(++ticks>9000)throw new IllegalStateException("Bounded fist review timeout phase"+phase);var a=player(s,0);var b=player(s,1);if(a==null||b==null)return;if(ticks%20==0)write("scenario-results.json",Map.of("phase",phase,"ticks",ticks,"results",results));
  if(phase==0){var w=s.getOverworld();w.getGameRules().get(net.minecraft.world.GameRules.DO_MOB_SPAWNING).set(false,s);for(int x=24;x<88;x++)for(int z=64;z<104;z++){w.setBlockState(new BlockPos(x,128,z),net.minecraft.block.Blocks.STONE.getDefaultState());for(int y=129;y<134;y++)w.setBlockState(new BlockPos(x,y,z),net.minecraft.block.Blocks.AIR.getDefaultState());}var types=List.of(FistRegistry.NOVICE,FistRegistry.EXPERIENCED,FistRegistry.CHAMPION);for(int i=0;i<3;i++){npcs[i]=types.get(i).create(w);npcs[i].refreshPositionAndAngles(42+i*12,129,80,90,0);w.spawnEntity(npcs[i]);}for(int i=0;i<2;i++){var p=player(s,i);p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.getInventory().clear();p.getInventory().setStack(8,new ItemStack(com.witchersbestiary.economy.Currency.WALLET));p.playerScreenHandler.sendContentUpdates();health[i]=p.getHealth();}fight(s,0,0);fight(s,1,1);phase=1;return;}
  if(phase==1){for(int i=0;i<2;i++){var active=FistFights.active(player(s,i));if(active!=null){rounds[i]=active;active.npc().setAiDisabled(false);}}if(rounds[0]==null||rounds[1]==null)return;if(FistFights.active(a)!=null||FistFights.active(b)!=null)return;for(int i=0;i<2;i++){results.put("tier"+i+"_stage",rounds[i].fight().stage.name());results.put("tier"+i+"_player_won",rounds[i].fight().playerWon);if(player(s,i).getHealth()!=health[i]||!npcs[i].isAlive())throw new IllegalStateException("Nonlethal fight changed health");}results.put("two_independent_bouts",true);fight(s,0,2);command(1,"wait",0);phase=2;return;}
  if(phase==2){if(FistFights.active(a)!=null){rounds[0]=FistFights.active(a);rounds[0].npc().setAiDisabled(false);}if(rounds[0]==null||FistFights.active(a)!=null)return;results.put("champion_stage",rounds[0].fight().stage.name());results.put("champion_player_won",rounds[0].fight().playerWon);results.put("all_npcs_alive",Arrays.stream(npcs).allMatch(FistNpc::isAlive));for(int i=0;i<2;i++)balances[i]=WalletTransactions.balance(player(s,i).getInventory().getStack(8));results.put("wallet_balances",balances);if(balances[0]+balances[1]==0)throw new IllegalStateException("No native victory/reward observed");fight(s,0,0);phase=3;return;}
  if(phase==3){if(FistFights.active(a)==null)return;npcs[0].setAiDisabled(false);results.put("active_bout_before_restart",true);Map<String,Object> resume=new LinkedHashMap<>();resume.put("npc",Arrays.stream(npcs).map(n->n.getUuid().toString()).toList());resume.put("balances",balances);resume.put("health",health);resume.put("results",results);write("fist-resume.json",resume);write("resume.json",Map.of());for(int i=0;i<2;i++)command(i,"wait",0);s.save(false,true,true);phase=99;s.stop(false);return;}
  if(phase==10){var data=JsonParser.parseString(Files.readString(dir.resolve("fist-resume.json"))).getAsJsonObject();for(int i=0;i<3;i++){var e=s.getOverworld().getEntity(UUID.fromString(data.getAsJsonArray("npc").get(i).getAsString()));if(e==null)return;if(!(e instanceof FistNpc n)||!n.pose().equals("idle"))throw new IllegalStateException("Stale NPC pose after restart");npcs[i]=(FistNpc)e;}for(int i=0;i<2;i++){var p=player(s,i);if(FistFights.active(p)!=null||WalletTransactions.balance(p.getInventory().getStack(8))!=data.getAsJsonArray("balances").get(i).getAsDouble())throw new IllegalStateException("Restart balance/session mismatch");if(FistRewards.get(s).claim(p))throw new IllegalStateException("Repeated crown delivery");}results.put("restart_clears_active_bout",true);fight(s,0,0);command(1,"wait",0);phase=11;return;}
  if(phase==11){var active=FistFights.active(a);if(active!=null){if(rounds[0]==null)command(1,"fistProof",0);rounds[0]=active;active.npc().setAiDisabled(false);}if(rounds[0]==null||FistFights.active(a)!=null)return;var saved=JsonParser.parseString(Files.readString(dir.resolve("fist-resume.json"))).getAsJsonObject();for(int i=0;i<2;i++)if(WalletTransactions.balance(player(s,i).getInventory().getStack(8))!=saved.getAsJsonArray("balances").get(i).getAsDouble())throw new IllegalStateException("Training rematch repeated reward");results.put("training_rematch_player_won",rounds[0].fight().playerWon);results.put("training_rematch_no_reward",true);results.putAll(new Gson().fromJson(saved.getAsJsonObject("results"),Map.class));npcs[0].getNavigation().stop();npcs[0].pose("knockout",100);a.teleport(s.getOverworld(),npcs[0].getX()-3,npcs[0].getY(),npcs[0].getZ(),-90,0);command(0,"fistPoseProof",npcs[0].getId());command(1,"wait",0);phase=12;return;}
  if(phase==12){var file=dir.resolve(names[0]+".reply.json");if(!Files.exists(file))return;var reply=JsonParser.parseString(Files.readString(file)).getAsJsonObject();if(!reply.get("status").getAsString().equals("fist-pose"))return;results.put("knockout_pose_review",true);results.put("restart_clears_active_bout",true);results.put("no_reward_replay",true);results.put("complete",true);write("complete.json",results);for(int i=0;i<2;i++)command(i,"stop",0);phase=99;}
 }catch(Throwable t){try{write("server-failure.json",Map.of("error",t.toString(),"phase",phase));}catch(Exception ignored){}phase=99;s.stop(false);}});}
}
